const D = { scale: 1, symmetry: 5, energy: .62, speed: 1, density: .5, hue: 210, x: .5, y: .5, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const TAU = 6.28318530718, PI = Math.PI, cl = (v,a,b)=>v<a?a:v>b?b:v;
const fr = i=>{ const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
function hsv(h,s,v){ h=((h%360)+360)%360/60; const c=v*s, x=c*(1-Math.abs(h%2-1)), m=v-c; let r,g,b;
  if(h<1){r=c;g=x;b=0;}else if(h<2){r=x;g=c;b=0;}else if(h<3){r=0;g=c;b=x;}else if(h<4){r=0;g=x;b=c;}else if(h<5){r=x;g=0;b=c;}else{r=c;g=0;b=x;}
  return [r+m,g+m,b+m]; }

// ---- coarse buffer, aspect-bucketed, long side ~200 (upscaled) ----
const asp = width/height, LS = 200;
let bw, bh;
if (asp>=1){ bw=LS; bh=Math.max(8, Math.round(LS/asp)); } else { bh=LS; bw=Math.max(8, Math.round(LS*asp)); }
const bkey = bw+'x'+bh;
if (!S.buf || S.bkey!==bkey){ if (S.buf && S.buf.remove) S.buf.remove(); S.buf = createGraphics(bw,bh); S.buf.pixelDensity(1); S.bkey = bkey; }
const g = S.buf;

// ---- symmetry order N: param + section step (aperiodic when odd) ----
let Nn = Math.round(cl(P.symmetry, 3, 12)) + (K.section % 4);
Nn = cl(Nn, 3, 16) | 0;

// ---- seeded per-wave phase + drift direction, rebuilt on seed/N change ----
if (S.seedUsed!==P.seed || S.N!==Nn){
  S.seedUsed = P.seed; S.N = Nn;
  const ph0 = new Float32Array(Nn), dsp = new Float32Array(Nn);
  for (let i=0;i<Nn;i++){
    ph0[i] = fr(i*3.7+1)*TAU;
    dsp[i] = (0.35 + fr(i*3.7+2)*0.9) * (fr(i*3.7+3)<0.5?-1:1);
  }
  S.ph0 = ph0; S.dsp = dsp;
  S.rot0 = fr(9)*TAU; S.hoff = fr(11)*80;
}

// ---- per-frame wave table (all rhythm from K, never frameCount) ----
const spd = cl(P.speed, .15, 4), en = cl(P.energy, 0, 1);
const baseRot = S.rot0 + K.t*0.02*spd;                  // whole crystal slowly rotates (K.t floor)
const drift = K.t*0.15*spd;                             // phase morph shimmer (K.t floor)
const bassBump = A.bass*0.5;                            // audio ON TOP, never sole motion
const ca = new Float32Array(Nn), sa = new Float32Array(Nn), ph = new Float32Array(Nn);
for (let i=0;i<Nn;i++){
  const a = i*PI/Nn + baseRot;
  ca[i] = Math.cos(a); sa[i] = Math.sin(a);
  ph[i] = S.ph0[i] + (drift + bassBump)*S.dsp[i];
}

// ---- frequency (scale, first poke) — capped so a 200px buffer never aliases ----
const F = TAU*16*cl(P.scale, .35, 2.1);                 // ~16 fringe cycles at scale 1
const mb = Math.max(bw,bh), cxo = (P.x-0.5), cyo = (P.y-0.5), invN = 1/Nn;
const expo = 0.55 + en*0.85 + K.intensity*0.35 + A.rms*0.6 + A.treble*0.3 + K.pulse*0.12*en;
const detail = cl(P.density,0,1);
const hb = ((P.hue + S.hoff + K.section*18) % 360 + 360) % 360, hr = hb/360;
const bands = 3 + detail*9;
const ST = P.style==='thermal'?1 : P.style==='blueprint'?2 : P.style==='sumi'?3 : P.style==='halftone'?4 : 0;
const HDM = [12,5,6,13, 4,0,1,7, 11,3,2,8, 15,10,9,14];
const inkC = hsv(hb, 0.6, 0.24);

g.loadPixels(); const px = g.pixels;
let idx = 0;
for (let yy=0; yy<bh; yy++){
  const cy = (yy - bh*0.5)/mb - cyo;
  for (let xx=0; xx<bw; xx++){
    const cx = (xx - bw*0.5)/mb - cxo;
    let s = 0;
    for (let i=0;i<Nn;i++){ s += Math.cos((cx*ca[i] + cy*sa[i])*F + ph[i]); }
    const v = s*invN;                                   // [-1,1]
    let r,gg,b;
    if (ST===1){                                        // thermal false-color
      let m = cl((v*0.5+0.5)*expo, 0, 1);
      m = cl(m + detail*0.16*Math.sin(m*PI*bands), 0, 1);
      r = Math.min(1, m*2.2);
      gg = Math.min(1, Math.max(0, m*2.0-0.55));
      b = Math.min(1, Math.max(0, m*3.2-2.1));
      b = Math.max(b, 0.09*(1-m));                       // indigo floor, no dead black
    } else if (ST===2){                                 // blueprint contour lines
      const f = (v*0.5+0.5)*bands, fp = f - Math.floor(f);
      const line = Math.pow(1 - Math.abs(fp-0.5)*2, 6);
      const base = 0.05 + (v*0.5+0.5)*0.06;
      r = cl(base*0.35 + line*0.20, 0, 1);
      gg = cl(base*0.80 + line*0.75, 0, 1);
      b = cl(base*1.50 + line*1.00, 0, 1);
    } else if (ST===3){                                 // sumi ink duotone (soft washes, dry-brush)
      let ink = cl((v*0.5+0.5 - 0.40)*(1.15+detail*1.5)*expo, 0, 1);
      ink = Math.pow(ink, 1.1);
      const paper = 0.90 - ink*0.80;
      r = paper*0.99; gg = paper*0.95; b = paper*0.86;
    } else if (ST===4){                                 // halftone clustered-dot screen
      const val = cl((v*0.5+0.5)*expo, 0, 1);
      const thr = (HDM[(yy&3)*4+(xx&3)]+0.5)/16;
      if (val > thr){ r=0.93; gg=0.90; b=0.82; }        // paper
      else { r=inkC[0]; gg=inkC[1]; b=inkC[2]; }        // hue-tinted ink dot
    } else {                                            // spectral iq cosine (anchor)
      let m = v*0.5+0.5;
      m = m + detail*0.16*Math.sin(m*PI*bands);
      const sh = Math.pow(cl(m*expo, 0, 1.2), 1.1);
      r = (0.5 + 0.5*Math.cos(TAU*(m + hr + 0.00)))*sh;
      gg = (0.5 + 0.5*Math.cos(TAU*(m + hr + 0.33)))*sh;
      b = (0.5 + 0.5*Math.cos(TAU*(m + hr + 0.67)))*sh;
      r = cl(r+0.02,0,1); gg = cl(gg+0.02,0,1); b = cl(b+0.02,0,1);
    }
    px[idx]=r*255; px[idx+1]=gg*255; px[idx+2]=b*255; px[idx+3]=255; idx+=4;
  }
}
g.updatePixels();

push();
drawingContext.imageSmoothingEnabled = (ST!==4);        // crisp dots for halftone, smooth else
if (P.alpha < 100) tint(0,0,100,P.alpha);               // translucent VJ compositing (no bg clear)
image(g, 0, 0, width, height);
pop();

// audio-reactive bloom ON TOP of the clk baseline (silent during validation -> baseline carries motion)
if (A.bass>0.02 || A.rms>0.02 || A.treble>0.02){
  push(); blendMode(ADD); noStroke();
  const glow = (A.bass*0.5 + A.rms*0.35)*en;
  fill(hb, 45, 100, cl(glow*20, 0, 22));                // partial full-frame add, never a strobe flash
  rect(0,0,width,height);
  if (A.treble>0.05){
    const n = Math.min(12, Math.floor(14*A.treble));
    for (let s=0;s<n;s++){ const a = fr(s*3.3 + Math.floor(K.beat*2))*TAU, rr = (0.15+fr(s*1.7)*0.32)*mb/LS*Math.min(width,height);
      fill((hb+40)%360, 20, 100, 45*A.treble);
      circle(width*0.5+Math.cos(a)*rr, height*0.5+Math.sin(a)*rr, Math.min(width,height)*0.006); }
  }
  blendMode(BLEND); pop();
}
